// scripts/lib/vendor/outputs.mjs
//
// Pure renderers for everything `npm run vendor` generates besides the
// vendored files themselves: vendor-manifest.json, the .gitignore /
// .vscodeignore marker blocks, and js/gen/vendor-deps.js. Unit-tested
// directly (tests/unit/vendor-outputs.test.mjs).

function byCodeUnit(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

export function sourceKindOf(dep) {
  if (dep.source.npm !== undefined) return "npm";
  if (dep.source.zip !== undefined) return "zip";
  return "files";
}

/** npm deps have no `version` field in the registry (forbidden); their
 * installed version is read back off the manifest entry's "pkg@version"
 * source (the same string node_modules/<pkg>/package.json produced it from). */
export function npmVersionFromEntries(dep, entries) {
  const entry = entries.find((e) => e.dep === dep.id);
  if (!entry) return null;
  const m = /^(.*)@([^@]+)$/.exec(entry.source);
  return m ? m[2] : null;
}

/** { generatedBy, deps, entries }: deps sorted by id (npm deps carry
 * their installed version too, read off `entries`), entries by plain
 * code-unit comparison of path (not localeCompare). */
export function buildManifest(resolvedDeps, entries) {
  const deps = resolvedDeps
    .map((dep) => {
      const kind = sourceKindOf(dep);
      const out = { id: dep.id, kind };
      const version = dep.version !== undefined ? dep.version : npmVersionFromEntries(dep, entries);
      if (version !== undefined && version !== null) out.version = version;
      if (kind === "zip") {
        out.source = dep.source.zip;
        out.sha256 = dep.source.sha256;
      }
      return out;
    })
    .sort((a, b) => byCodeUnit(a.id, b.id));

  return {
    generatedBy: "scripts/vendor.mjs",
    deps,
    entries: [...entries].sort((a, b) => byCodeUnit(a.path, b.path)),
  };
}

export function serializeManifest(manifest) {
  return JSON.stringify(manifest, null, 2) + "\n";
}

// ---------------------------------------------------------------------------
// Marked block rendering + splicing, shared by .gitignore and .vscodeignore.
// ---------------------------------------------------------------------------

const BEGIN_RE = /^# BEGIN vendor-deps:.*$/m;
const END_LINE = "# END vendor-deps";

export function normalizeLf(text) {
  return text.replace(/\r\n/g, "\n");
}

export function renderGitignoreBlock(resolvedDeps) {
  const lines = resolvedDeps.filter((d) => d.fetchOnly).map((d) => `vendor/${d.dir}/`);
  return ["# BEGIN vendor-deps: generated by `npm run vendor` from scripts/vendor-deps.mjs (fetchOnly), do not edit", ...lines, END_LINE].join("\n");
}

export function renderVscodeignoreBlock(resolvedDeps) {
  const lines = resolvedDeps.filter((d) => d.vscode === false).map((d) => `vendor/${d.dir}/**`);
  return ["# BEGIN vendor-deps: generated by `npm run vendor` from scripts/vendor-deps.mjs (vscode: false), do not edit", ...lines, END_LINE].join("\n");
}

/** Replaces the marked block in `content` with `blockText`, or appends
 * it (with a blank line before it) if no markers are present yet. CRLF
 * input is normalized to LF; the result always ends each line with LF. */
export function spliceMarkedBlock(content, blockText) {
  const normalized = normalizeLf(content);
  const beginMatch = normalized.match(BEGIN_RE);
  if (!beginMatch) {
    const sep = normalized === "" || normalized.endsWith("\n") ? "" : "\n";
    return normalized + sep + blockText + "\n";
  }
  const beginIndex = beginMatch.index;
  const endIndex = normalized.indexOf(END_LINE, beginIndex);
  if (endIndex === -1) {
    throw new Error("found a '# BEGIN vendor-deps' marker with no matching '# END vendor-deps' marker");
  }
  const tail = normalized.slice(endIndex + END_LINE.length).replace(/^\n/, "");
  return normalized.slice(0, beginIndex) + blockText + "\n" + tail;
}

// ---------------------------------------------------------------------------
// js/gen/vendor-deps.js
// ---------------------------------------------------------------------------

export function renderVendorDepsJs(resolvedDeps, manifestEntries) {
  const obj = {};
  for (const dep of [...resolvedDeps].sort((a, b) => byCodeUnit(a.id, b.id))) {
    const version = dep.version !== undefined ? dep.version : npmVersionFromEntries(dep, manifestEntries);
    const entry = { dir: dep.dir, name: dep.name, version, licenseUrl: dep.license.url };
    if (dep.module) entry.module = dep.module;
    if (dep.vscode === false) entry.vscode = false;
    obj[dep.id] = entry;
  }
  return `// Generated by \`npm run vendor\` from scripts/vendor-deps.mjs. Do not edit.\nwindow.MTLX_VENDOR_DEPS = ${JSON.stringify(obj, null, 2)};\n`;
}
